describe('Polling Stop on Page Navigation', () => {
  beforeEach(() => {
    cy.visit('/polling-page');
  });

  it('should stop polling when user navigates away from the page', () => {
    // Intercept the polling API endpoint
    cy.intercept('GET', '/api/polling/data').as('pollingRequest');

    // Verify initial polling is active
    cy.wait('@pollingRequest');
    cy.get('[data-testid="polling-status"]').should('contain', 'Active');

    // Navigate to another page
    cy.get('[data-testid="nav-link"]').click();
    cy.url().should('not.include', '/polling-page');

    // Verify polling has stopped by waiting for a timeout without intercepting
    cy.intercept('GET', '/api/polling/data').as('pollingRequestAfterNav');
    cy.wait(5000);

    // Verify no more polling requests were made
    cy.get('[data-testid="polling-status"]').should('not.exist');
    cy.get('[data-testid="polling-indicator"]').should('not.exist');
  });

  it('should handle navigation back to page and resume polling', () => {
    // Intercept the polling API endpoint
    cy.intercept('GET', '/api/polling/data').as('pollingRequest1');

    // Initial page load and polling starts
    cy.wait('@pollingRequest1');
    cy.get('[data-testid="polling-status"]').should('contain', 'Active');

    // Navigate away
    cy.get('[data-testid="nav-link"]').click();
    cy.url().should('not.include', '/polling-page');

    // Navigate back to the page
    cy.get('[data-testid="back-to-polling"]').click();
    cy.url().should('include', '/polling-page');

    // Verify polling resumes
    cy.intercept('GET', '/api/polling/data').as('pollingRequestResume');
    cy.wait('@pollingRequestResume');

    cy.get('[data-testid="polling-status"]').should('contain', 'Active');
    cy.get('[data-testid="polling-indicator"]').should('be.visible');
  });
});
